if ($json.status !== 'success' || $json.data?.resultType !== 'vector' ||
    !Array.isArray($json.data.result) || $json.data.result.length === 0) {
  throw new Error('missing complete queue telemetry');
}
const pairs = new Map();
let busy = 0;
for (const row of $json.data.result) {
  const metric = row.metric;
  const name = metric?.__name__;
  if (!metric || metric.model_name !== 'qwen3.8-27b' ||
      !['vllm:num_requests_running', 'vllm:num_requests_waiting'].includes(name) ||
      !Array.isArray(row.value) || row.value.length !== 2 ||
      typeof row.value[0] !== 'number' || !Number.isFinite(row.value[0]) || row.value[0] <= 0 ||
      typeof row.value[1] !== 'string' || row.value[1].trim() === '') {
    throw new Error('invalid queue telemetry shape');
  }
  if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(row.value[1])) {
    throw new Error('invalid queue number representation');
  }
  const value = Number(row.value[1]);
  if (!Number.isFinite(value) || value < 0) throw new Error('invalid queue count');
  const labels = Object.entries(metric).filter(([key]) => key !== '__name__');
  if (labels.some(([, value]) => typeof value !== 'string')) throw new Error('invalid queue labels');
  labels.sort(([a], [b]) => a.localeCompare(b));
  const key = JSON.stringify(labels);
  const pair = pairs.get(key) || new Set();
  if (pair.has(name)) throw new Error('duplicate queue series');
  pair.add(name);
  pairs.set(key, pair);
  busy += value;
}
if (!Number.isFinite(busy) || [...pairs.values()].some(pair => pair.size !== 2)) {
  throw new Error('incomplete queue telemetry');
}
return [{json: {action: busy === 0 ? 'step' : 'skip', busy}}];
